class LRUCache
  def initialize(capacity)
    unless capacity.is_a?(Integer) && capacity.positive?
      raise ArgumentError, "capacity must be a positive integer"
    end

    @capacity = capacity
    # Ruby hashes preserve insertion order: least recently used keys come first.
    @entries = {}
  end

  # Returns nil if the key is not cached.
  def get(key)
    return nil unless @entries.key?(key)

    @entries[key] = @entries.delete(key)
  end

  def put(key, value)
    @entries.delete(key)
    @entries[key] = value
    @entries.shift if @entries.size > @capacity
    value
  end
end
